<?php
declare(strict_types=1);use Acorn\SafetyHealthcheck\Assessment\CompletionService;use Acorn\SafetyHealthcheck\Reports\ReportDataBuilder;
final class ReportConsistencyTest extends IntegrationTestCase{public function test_canonical_report_has_same_counts_and_findings_as_snapshot():void{add_filter('pre_wp_mail','__return_true');[$s,$token]=$this->assessed();$result=(new CompletionService)->complete($token,['first_name'=>'A','last_name'=>'B','company'=>'Consistency Ltd','email'=>'consistent@example.test','audit_requested'=>false]);$report=(new ReportDataBuilder)->build($result['assessment_id']);self::assertSame($report['meta']['areas_assessed'],array_sum([$report['summary']['priority_count'],$report['summary']['review_count'],$report['summary']['addressed_count']]));self::assertSame('What appears to be working',$report['sections']['addressed']['label']);self::assertArrayNotHasKey('service_tags',$report);}}
